1	const PROCESSING_FEE = 5;
2	
3	export type Item = {
4	  type: string;
5	  material?: string;
6	  enchantment?: number;
7	  cursed?: boolean;
8	};
9	
10	// `op` is typed as a plain string because a scenario arrives as untrusted JSON;
11	// the discriminating narrowing happens in `runScenario`.
12	export type QuoteStep = {
13	  op: string;
14	  items: Item[];
15	};
16	
17	export type Damage = {
18	  itemType: string;
19	  amount: number;
20	};
21	
22	export type Incident = {
23	  cause: string;
24	  damages: Damage[];
25	};
26	
27	export type ClaimStep = {
28	  op: string;
29	  policy: number;
30	  incident: Incident;
31	};
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	const isClaimStep = (step: Step): step is ClaimStep => step.op === "claim";
36	
37	export type Customer = {
38	  yearsWithMHPCO: number;
39	};
40	
41	export type Scenario = {
42	  customer: Customer;
43	  steps: Step[];
44	};
45	
46	export type QuoteResult = {
47	  premium: number;
48	};
49	
50	export type ClaimResult = {
51	  payout: number;
52	  remainingCap: number;
53	};
54	
55	export type StepResult = QuoteResult | ClaimResult;
56	
57	export type ScenarioResults = {
58	  results: StepResult[];
59	};
60	
61	const BASE_PREMIUMS: Record<string, number> = {
62	  sword: 100,
63	  amulet: 60,
64	  staff: 80,
65	  potion: 40,
66	  rune: 25,
67	  moonstone: 25,
68	};
69	
70	// Percentages are applied as `amount * percent / 100` rather than
71	// `amount * 1.percent`, so that integer amounts stay exact: 100 * 1.1 is
72	// 110.00000000000001 in binary floating point, while 100 * 10 / 100 is 10.
73	const percentOf = (amount: number, percent: number): number =>
74	  (amount * percent) / 100;
75	
76	const basePremium = (item: Item): number => BASE_PREMIUMS[item.type];
77	
78	const BLOCK_SIZE = 3;
79	const BLOCK_BASE_PREMIUM = 60;
80	
81	// Items of the same type are priced together, so a policy is partitioned into
82	// same-type groups before any group pricing rule is applied.
83	const groupByType = (items: Item[]): Item[][] => {
84	  const groupsByType = new Map<string, Item[]>();
85	  for (const item of items) {
86	    const alike = groupsByType.get(item.type) ?? [];
87	    alike.push(item);
88	    groupsByType.set(item.type, alike);
89	  }
90	  return [...groupsByType.values()];
91	};
92	
93	const sumOf = <T>(values: T[], amount: (value: T) => number): number =>
94	  values.reduce((total, value) => total + amount(value), 0);
95	
96	// A building block of exactly 3 alike components is offered at a flat rate.
97	const groupBasePremium = (alike: Item[]): number =>
98	  alike.length === BLOCK_SIZE
99	    ? BLOCK_BASE_PREMIUM
100	    : sumOf(alike, basePremium);
101	
102	const itemsBasePremium = (items: Item[]): number =>
103	  sumOf(groupByType(items), groupBasePremium);
104	
105	const CURSE_SURCHARGE_PERCENT = 50;
106	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
107	const HIGH_ENCHANTMENT_LEVEL = 5;
108	
109	const isCursed = (item: Item): boolean => item.cursed === true;
110	
111	// Components such as runes carry no enchantment field; an absent level counts
112	// as 0, so they fall below every enchantment threshold.
113	const enchantmentLevel = (item: Item): number => item.enchantment ?? 0;
114	
115	const isHighlyEnchanted = (item: Item): boolean =>
116	  enchantmentLevel(item) >= HIGH_ENCHANTMENT_LEVEL;
117	
118	// Each rule charges its percent of the affected item's own base premium.
119	type ItemSurchargeRule = {
120	  applies: (item: Item) => boolean;
121	  percent: number;
122	};
123	
124	const ITEM_SURCHARGE_RULES: ItemSurchargeRule[] = [
125	  { applies: isCursed, percent: CURSE_SURCHARGE_PERCENT },
126	  { applies: isHighlyEnchanted, percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT },
127	];
128	
129	// Item-specific surcharges apply to the base premium of the affected item.
130	// Several can apply to the same item, so every matching rule is summed.
131	const itemSurcharges = (item: Item): number => {
132	  const base = basePremium(item);
133	  return sumOf(
134	    ITEM_SURCHARGE_RULES.filter((rule) => rule.applies(item)),
135	    (rule) => percentOf(base, rule.percent),
136	  );
137	};
138	
139	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
140	const LOYALTY_DISCOUNT_PERCENT = 20;
141	const LOYALTY_YEARS = 2;
142	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
143	
144	const isLongStanding = (customer: Customer): boolean =>
145	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
146	
147	// Who is buying, as opposed to what is being insured. Policy-wide modifiers
148	// depend only on this; item pricing depends only on the items.
149	type Customership = {
150	  customer: Customer;
151	  priorContracts: number;
152	};
153	
154	// Policy-wide modifiers adjust the policy base; item-specific surcharges are
155	// computed against each item's own unmodified base. Both are ADDITIVE against
156	// the base rather than compounding, so they are summed side by side and never
157	// nested inside one another. Discounts are negative percentages.
158	//
159	// Each modifier is written as its own percent-of-the-policy-base summand, so
160	// adding one never changes how the others are computed.
161	const policyModifiers = (
162	  policyBase: number,
163	  { customer, priorContracts }: Customership,
164	): number => {
165	  const firstInsurance = percentOf(policyBase, FIRST_INSURANCE_SURCHARGE_PERCENT);
166	  const loyalty = isLongStanding(customer)
167	    ? -percentOf(policyBase, LOYALTY_DISCOUNT_PERCENT)
168	    : 0;
169	  const followUp =
170	    priorContracts > 0
171	      ? -percentOf(policyBase, FOLLOW_UP_DISCOUNT_PERCENT)
172	      : 0;
173	  return firstInsurance + loyalty + followUp;
174	};
175	
176	const policyPremium = (items: Item[], customership: Customership): number => {
177	  const policyBase = itemsBasePremium(items);
178	  return (
179	    policyBase +
180	    policyModifiers(policyBase, customership) +
181	    sumOf(items, itemSurcharges)
182	  );
183	};
184	
185	// Amounts are rounded in the MHPCO's favor, so the direction depends on which
186	// way the money flows: premiums (customer pays) round up. The payout
187	// counterpart rounds down; it is named for its direction for the same reason.
188	const roundUpPremium = (amount: number): number => Math.ceil(amount);
189	const roundDownPayout = (amount: number): number => Math.floor(amount);
190	
191	const isOnPriceList = (item: Item): boolean => item.type in BASE_PREMIUMS;
192	
193	// The office only insures what is on its price list. One uninsurable item
194	// rejects the whole policy, so the search stops at the first one found.
195	const rejectUnknownItemTypes = (items: Item[]): void => {
196	  const uninsurable = items.find((item) => !isOnPriceList(item));
197	  if (uninsurable) {
198	    throw new Error(
199	      `the MHPCO does not insure items of type ${uninsurable.type}`,
200	    );
201	  }
202	};
203	
204	const quote = (step: QuoteStep, customership: Customership): QuoteResult => {
205	  rejectUnknownItemTypes(step.items);
206	  return {
207	    premium: roundUpPremium(
208	      PROCESSING_FEE + policyPremium(step.items, customership),
209	    ),
210	  };
211	};
212	
213	const INSURANCE_VALUES: Record<string, number> = {
214	  sword: 1000,
215	  amulet: 600,
216	  staff: 800,
217	  potion: 400,
218	  rune: 250,
219	  moonstone: 250,
220	};
221	
222	const insuranceValue = (item: Item): number => INSURANCE_VALUES[item.type];
223	
224	const DEDUCTIBLE = 100;
225	const CAP_MULTIPLE = 2;
226	
227	// A policy, once quoted, carries the cap still available to future claims.
228	type Policy = {
229	  items: Item[];
230	  remainingCap: number;
231	};
232	
233	const openPolicy = (items: Item[]): Policy => ({
234	  items,
235	  remainingCap: CAP_MULTIPLE * sumOf(items, insuranceValue),
236	});
237	
238	// A separate, higher threshold than the premium surcharge's: enchantment >= 5
239	// makes an item dearer to insure, enchantment >= 8 makes it less reimbursable.
240	// The two rules move independently, so they keep independent constants.
241	const HALVED_REIMBURSEMENT_LEVEL = 8;
242	const HALVED_REIMBURSEMENT_PERCENT = 50;
243	
244	const isHeavilyEnchanted = (item: Item): boolean =>
245	  enchantmentLevel(item) >= HALVED_REIMBURSEMENT_LEVEL;
246	
247	// Damage to a heavily enchanted item is only half reimbursed. The clause
248	// reduces the damage amount; the deductible is taken afterwards.
249	const reimbursedDamage = (amount: number, item: Item): number =>
250	  isHeavilyEnchanted(item)
251	    ? percentOf(amount, HALVED_REIMBURSEMENT_PERCENT)
252	    : amount;
253	
254	const damagePayout = (damage: Damage, items: Item[]): number => {
255	  const item = items.find((insured) => insured.type === damage.itemType)!;
256	  return reimbursedDamage(damage.amount, item) - DEDUCTIBLE;
257	};
258	
259	// A tally of how often each type occurs. A type that never occurs is absent
260	// from the map rather than present with 0, so reads go through `countOf`.
261	type TypeCounts = Map<string, number>;
262	
263	const countOf = (counts: TypeCounts, type: string): number =>
264	  counts.get(type) ?? 0;
265	
266	const countByType = <T>(
267	  values: T[],
268	  typeOf: (value: T) => string,
269	): TypeCounts => {
270	  const counts: TypeCounts = new Map();
271	  for (const value of values) {
272	    const type = typeOf(value);
273	    counts.set(type, countOf(counts, type) + 1);
274	  }
275	  return counts;
276	};
277	
278	// A damage is a loss, never a gain, so a negative amount is not a claim the
279	// office can process.
280	const rejectNegativeDamage = (damages: Damage[]): void => {
281	  for (const damage of damages) {
282	    if (damage.amount < 0) {
283	      throw new Error(
284	        `damage to ${damage.itemType} has a negative amount ${damage.amount}`,
285	      );
286	    }
287	  }
288	};
289	
290	// A policy cannot be claimed against more times per item type than it covers,
291	// so the whole claim is rejected before any of it is paid.
292	const rejectOverClaimed = (damages: Damage[], items: Item[]): void => {
293	  const insured = countByType(items, (item) => item.type);
294	  const claimed = countByType(damages, (damage) => damage.itemType);
295	
296	  for (const [type, claims] of claimed) {
297	    const covered = countOf(insured, type);
298	    if (claims > covered) {
299	      throw new Error(
300	        `claim covers ${claims} ${type} damage(s) but the policy insures ${covered}`,
301	      );
302	    }
303	  }
304	};
305	
306	// The total payout per policy is capped, so a claim pays out no more than the
307	// cap the policy has left. Only the damages are needed, not the whole step:
308	// the incident's cause does not affect what is paid.
309	const claim = (damages: Damage[], policy: Policy): ClaimResult => {
310	  rejectNegativeDamage(damages);
311	  rejectOverClaimed(damages, policy.items);
312	
313	  // Only the final payout is rounded; the cap is then charged exactly what was
314	  // paid out, which also keeps the remaining cap a whole number.
315	  const uncappedPayout = roundDownPayout(
316	    sumOf(damages, (damage) => damagePayout(damage, policy.items)),
317	  );
318	  const payout = Math.min(uncappedPayout, policy.remainingCap);
319	  policy.remainingCap -= payout;
320	  return { payout, remainingCap: policy.remainingCap };
321	};
322	
323	export const runScenario = ({
324	  customer,
325	  steps,
326	}: Scenario): ScenarioResults => {
327	  // A claim's `policy` is the zero-based index of the STEP that quoted it, so
328	  // policies are keyed by step index. The customer's prior-contract count is a
329	  // different number — it counts only quote steps — so the two are tracked
330	  // separately.
331	  const policies = new Map<number, Policy>();
332	  let priorContracts = 0;
333	
334	  const results = steps.map((step, index) => {
335	    if (isClaimStep(step)) {
336	      return claim(step.incident.damages, policies.get(step.policy)!);
337	    }
338	    policies.set(index, openPolicy(step.items));
339	    // Quoted against the contracts that came BEFORE this one, so this step is
340	    // counted only after it has been priced.
341	    const result = quote(step, { customer, priorContracts });
342	    priorContracts += 1;
343	    return result;
344	  });
345	
346	  return { results };
347	};
